const api = express.Router();

api.get('/health', (req,res)=>res.json({ ok:true, persistencia: USE_PG?'postgres':'json', ts:new Date().toISOString() }));

api.post('/auth/login', h(async (req,res)=>{
  const { email, password } = req.body || {};
  const u = await repo.findUserByEmail(String(email||'').toLowerCase());
  if(!u || u.status!=='activo' || !verifyPw(password,u.password_hash,u.password_salt))
    return res.status(401).json({ error:{ code:'CREDENCIALES', message:'Correo o contraseña incorrectos' } });
  if(u.tenant_id){ const t=await repo.getTenant(u.tenant_id); if(t && t.status!=='activo') return res.status(403).json({ error:{ code:'EMPRESA_INACTIVA', message:'La empresa está inactiva' } }); }
  const token=randomToken(); await repo.createSession(token,u.id,Date.now()+7*24*3600*1000);
  res.json({ token, user: await toPublicUser(u) });
}));
api.get('/auth/me', authMw, h(async (req,res)=>res.json(await toPublicUser(req.user))));
api.post('/auth/logout', authMw, h(async (req,res)=>{ const t=(req.headers.authorization||'').replace(/^Bearer /,''); await repo.deleteSession(t); res.json({ ok:true }); }));
api.post('/auth/change-password', authMw, h(async (req,res)=>{
  const { current, next } = req.body || {};
  if(!next || String(next).length<6) return res.status(400).json({ error:{ code:'VALIDACION', message:'La nueva contraseña debe tener al menos 6 caracteres' } });
  const u=await repo.getUserById(req.user.id);
  if(!verifyPw(current, u.password_hash, u.password_salt)) return res.status(401).json({ error:{ code:'CLAVE_ACTUAL', message:'La contraseña actual es incorrecta' } });
  const hp=hashPw(next);
  await repo.updateUser(u.id, { password_hash:hp.hash, password_salt:hp.salt });
  res.json({ ok:true });
}));

